TopCompaniesByInvoiceCountFunded = {
	init: async function (app, container) {
		app = app || session.app;
		container = container || $(".component[name=TopCompaniesByInvoiceCountFunded]");
		TopCompaniesByInvoiceCountFunded.buildLeaderboard({data: await TopCompaniesByInvoiceCountFunded.getData(app) }, container);
	},

	getData: async function(app) {
		var chartData = await api.get("B2B/Invoice/FromSystem(SystemId='" + app.Config.B2B.SourceSystem + "')?$apply=filter(FundingState eq 'Paid')/groupby((CreditorName), aggregate(Id with countdistinct as Total))");
		return chartData.sort((a, b) => b.Total - a.Total).slice(0, 10);
	},

	buildLeaderboard: function (data, container) {
		var maxValue = data.data.length > 0 ? data.data[0].Total : 0;
		var itemTemplate = $('[name=TopCompaniesByInvoiceCountFunded].template').first().html().replace("[MAX]", maxValue);

		$('[name=leaderboardTarget]', container).kendoListView({
			dataSource: data,
			template: kendo.template(itemTemplate),
			selectable: true,
			dataBound: function (e) {
				var percentiles = $('.percentage', e.sender.element);
				percentiles.map(function (index, element) {
					var val = $(element).attr('data-percentage');
					var percent = parseFloat(val.split('/')[0]) / (parseFloat(val.split('/')[1]) / 100);
					$(element).css('width', percent + '%');
				});
			},
		});
	}
}
